// Generate one editorial draft. Credentials are configured only in n8n.
const QUEUE_URL = 'https://raw.githubusercontent.com/mikah33/cortisolplus-web/main/automation/editorial-queue.json';
const ANTHROPIC_KEY = 'REPLACE_ANTHROPIC_KEY';
const ANTHROPIC_MODEL = 'claude-sonnet-4-5-20250929';
const REPO_API = 'https://api.github.com/repos/mikah33/cortisolplus-web';

const [queue, files, refs] = await Promise.all([
  this.helpers.httpRequest({ method: 'GET', url: QUEUE_URL, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: REPO_API + '/contents/src/content/blog?ref=main', json: true }),
  this.helpers.httpRequest({ method: 'GET', url: REPO_API + '/git/matching-refs/heads/content/', json: true }),
]);
if (![queue, files, refs].every(Array.isArray)) throw new Error('Editorial queue or repository inventory is invalid.');

const data = $getWorkflowStaticData('global');
if (!Array.isArray(data.usedSlugs)) data.usedSlugs = [];
const existing = new Set([
  ...data.usedSlugs,
  ...files.map(f => f.name.replace(/[.]mdx$/, '')),
  ...refs.map(r => r.ref.replace('refs/heads/content/', '')),
]);
const topic = queue.find(t => !existing.has(t.slug));
// A completed queue is a successful no-op, not a reason to generate unapproved topics.
if (!topic) return [];
if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(topic.slug) || !topic.title || !topic.primaryKeyword) {
  throw new Error('Invalid editorial topic.');
}
data.usedSlugs.push(topic.slug);

const prompt = `Write an educational draft for Cortisol+, a stress and HRV wellness app. It does not measure cortisol, diagnose hormone disorders, or have established clinical accuracy. Topic brief: ${JSON.stringify(topic)}.
Return ONLY a JSON object with title, description, tags (array of strings), and body (plain Markdown, no HTML, JSX, import, export, braces or frontmatter). Aim for 500-800 useful words, without padding or repetitive keyword use. Start with a direct answer; then explain practical steps and limitations.
Use only the supplied source URLs for citations. A supplied URL is not proof of a claim: omit details you cannot support, and do not claim to have opened a source or tested an app. Do not invent statistics, reviewers, authors, customer stories, UI labels, clinical validation or competitor testing. Avoid dosing, diagnosis from symptoms or quiz results, and promises of hormone reduction. Include the supplied internal links where useful. End with a concise educational disclaimer. This remains a draft until a human checks every claim and source.`;

try {
  const result = await this.helpers.httpRequest({
    method: 'POST', url: 'https://api.anthropic.com/v1/messages',
    headers: { 'x-api-key': ANTHROPIC_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
    body: { model: ANTHROPIC_MODEL, max_tokens: 4096, messages: [{ role: 'user', content: prompt }] },
    json: true,
  });
  const raw = result.content?.find(b => b.type === 'text')?.text || '';
  const article = JSON.parse(raw.replace(/^```(?:json)?\s*\n/, '').replace(/\n```\s*$/, '').trim());
  if (![article.title, article.description, article.body].every(v => typeof v === 'string' && v.trim())) throw new Error('Missing article fields');
  if (article.body.length < 200 || article.body.length > 40000 || /^\s*(import|export)\s|[<>{}]/m.test(article.body)) throw new Error('Invalid plain Markdown body');
  return [{ json: { slug: topic.slug, title: article.title, description: article.description, tags: Array.isArray(article.tags) ? article.tags.filter(t => typeof t === 'string') : [], body: article.body } }];
} catch (error) {
  data.usedSlugs = data.usedSlugs.filter(s => s !== topic.slug);
  // Do not serialize HTTP errors, which can include request credentials.
  throw new Error('Draft generation failed. Check API availability and JSON/plain-Markdown output; no article was dispatched.');
}
